<?php
require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_role(['administrador','profesor','estudiante']);require_once __DIR__.'/../models/AsistenciaModel.php';$m=new AsistenciaModel($pdo);$id=(int)($_GET['id']??0);$accion=$_GET['accion']??'listar';$puedeGestionar=puede_gestionar_academico();
if(es_estudiante()){$q=$pdo->prepare("SELECT a.*,CONCAT(u.nombre,' ',u.apellido) estudiante,c.nombre_curso,c.codigo FROM asistencia a JOIN inscripciones i ON i.id_inscripcion=a.id_inscripcion JOIN estudiantes e ON e.id_estudiante=i.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN cursos c ON c.id_curso=i.id_curso WHERE e.id_usuario=? ORDER BY a.fecha DESC");$q->execute([$_SESSION['id_usuario']]);$registros=$q->fetchAll();$accion='listar';$id=0;}else{$registros=$m->obtenerTodas();}
if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['administrador','profesor']);validar_csrf();try{if(($_POST['accion']??'')==='eliminar'){$m->eliminar((int)$_POST['id']);flash('success','Registro de asistencia eliminado.');}else{if($id)$m->editar($id,$_POST);else$m->crear($_POST);flash('success',$id?'Asistencia actualizada.':'Asistencia registrada.');}}catch(Throwable $e){flash('error','No se pudo guardar la asistencia.');}redir('/controllers/asistencia.php');}$registro=($id&&$puedeGestionar)?$m->obtenerPorId($id):null;$tituloPagina='Asistencia';require __DIR__.'/../views/asistencia/index.php';
